/* ---------------------------------------------------------------------------
 * Lua redis.* functions implementations.
 * ------------------------------------------------------------------------- */
void freeLuaRedisArgv(robj **argv, int argc, int argv_len);

/* Cached argv array across calls. */
static robj **lua_argv = NULL;
static int lua_argv_size = 0;

/* Cache of recently used small arguments to avoid malloc calls. */
static robj *lua_args_cached_objects[LUA_CMD_OBJCACHE_SIZE];
static size_t lua_args_cached_objects_len[LUA_CMD_OBJCACHE_SIZE];

static robj **luaArgsToRedisArgv(lua_State *lua, int *argc, int *argv_len) {
    int j;
    int arg_type;

    /* Require at least one argument */
    *argc = lua_gettop(lua);
    if (*argc == 0) {
        luaPushError(lua, "Please specify at least one argument for this redis lib call");
        return NULL;
    }

    /* Build the arguments vector (reuse a cached argv from last call) */
    if (lua_argv_size < *argc) {
        size_t bytes = sizeof(robj*) * (size_t)(*argc);
        lua_argv = zrealloc(lua_argv, bytes);
        lua_argv_size = *argc;
    }
    *argv_len = lua_argv_size;

    for (j = 0; j < *argc; j++) {
        char *obj_s;
        size_t obj_len;
        char dbuf[64];
        robj *cached;
        sds s;
        unsigned char sds_flags;
        int used_cache;

        arg_type = lua_type(lua,j+1);
        if (arg_type == LUA_TNUMBER) {
            /* We can't use lua_tolstring() for number -> string conversion
             * since Lua uses a format specifier that loses precision. */
            lua_Number num = lua_tonumber(lua,j+1);
            obj_len = fpconv_dtoa((double)num, dbuf);
            dbuf[obj_len] = '\0';
            obj_s = dbuf;
        } else {
            obj_s = (char*)lua_tolstring(lua,j+1,&obj_len);
            if (obj_s == NULL) break; /* Not a string. */
        }

        /* Try to use a cached object. */
        used_cache = 0;
        cached = (j < LUA_CMD_OBJCACHE_SIZE) ? lua_args_cached_objects[j] : NULL;
        if (cached != NULL) {
            if (lua_args_cached_objects_len[j] >= obj_len) {
                s = cached->ptr;
                lua_argv[j] = cached;
                lua_args_cached_objects[j] = NULL;
                memcpy(s,obj_s,obj_len+1);
                sds_flags = s[-1];
                switch(sds_flags & SDS_TYPE_MASK) {
                    case SDS_TYPE_5:
                        {
                            unsigned char *fp = ((unsigned char*)s)-1;
                            *fp = SDS_TYPE_5 | (obj_len << SDS_TYPE_BITS);
                        }
                        break;
                    case SDS_TYPE_8:
                        SDS_HDR(8,s)->len = obj_len;
                        break;
                    case SDS_TYPE_16:
                        SDS_HDR(16,s)->len = obj_len;
                        break;
                    case SDS_TYPE_32:
                        SDS_HDR(32,s)->len = obj_len;
                        break;
                    case SDS_TYPE_64:
                        SDS_HDR(64,s)->len = obj_len;
                        break;
                }
                used_cache = 1;
            }
        }
        if (!used_cache) {
            /* Small strings use EMBSTR so the SDS payload shares the object allocation. */
            if (obj_len <= 44) {
                robj *o = zmalloc(sizeof(robj)+sizeof(struct sdshdr8)+obj_len+1);
                struct sdshdr8 *sh = (void*)(o+1);
                o->type = OBJ_STRING;
                o->encoding = OBJ_ENCODING_EMBSTR;
                o->ptr = sh+1;
                o->refcount = 1;
                o->lru = 0;
                sh->len = obj_len;
                sh->alloc = obj_len;
                sh->flags = SDS_TYPE_8;
                if (obj_len > 0) {
                    memcpy(sh->buf,obj_s,obj_len);
                    sh->buf[obj_len] = '\0';
                } else {
                    sh->buf[0] = '\0';
                }
                lua_argv[j] = o;
            } else {
                lua_argv[j] = createObject(OBJ_STRING, sdsnewlen(obj_s, obj_len));
            }
        }
    }

    /* Pop all arguments from the stack, we do not need them anymore
     * and this way we guaranty we will have room on the stack for the result. */
    lua_pop(lua, *argc);

